    var servicesRendered = false;
    var aboutRendered = false;
    var testimonialsRendered = false;
    var contactRendered = false;
    var photosRendered = false;
    var locationsRendered = false;

    function DisplayPage(page) {
        if (!$(page).hasClass("show")) {
            $("#pages div.collapse.show").collapse("hide");
        }
        $(page).collapse("show");

        if(page == "#homePage")
        {
            var carousel = $(".slick-slider");
            if(carousel != null)
            {
                carousel.slick('refresh');
            }
        }

        if (page == "#testimonialsPage") {
             // Load Testimonials via Ajax if not already loaded
            if (!testimonialsRendered) {
                ShowLoading();
                $.get('/Home/GetTestimonialsContent', {id: 5046, template: "Template_6"}, function (data) {
                    if (data != "")
                    {
                        $("#testimonialsPage").append(data);
                    }
                }).always(function() {
                    HideLoading();
                    testimonialsRendered = true;
                    GetReviewData(0);
                });
            }

            $("html, body").animate({ scrollTop: 0 }, "fast");
        }

        if (page == "#aboutPage") {
            // Load About via Ajax if not already loaded
            if (!aboutRendered) {
                ShowLoading();
                $.get('/Home/GetAboutContent', { id: 5046, template: "Template_6"}, function (data) {
                    if (data != "")
                    {
                        $("#aboutPage").append(data);
                        $.getScript("https://web.archive.org/web/20220405071626/https://maps.googleapis.com/maps/api/js?key=AIzaSyB2UoPWVWPR8WrIFK_zqJ5nTN1NvGm9dqY&callback=initMap");
                    }
                }).always(function() {
                    HideLoading();
                    aboutRendered = true;
                });
            }
        }

        if (page == "#servicesPage") {
            // Load Services via Ajax if not already loaded
            if (!servicesRendered) {
                ShowLoading();
                $.get('/Home/GetServicesContent', { id: 5046, template: "Template_6"}, function (data) {
                    if (data != "")
                    {
                        $("#servicesPage").append(data);
                    }
                }).always(function() {
                    HideLoading();
                    servicesRendered = true;
                });
            }
        }

        if (page == "#imageryPage") {
            // Load photos via Ajax if not already loaded
            if (!photosRendered) {
                ShowLoading();
                $.get('/Home/GetPhotosContent', { id: 5046, template: "Template_6"}, function (data) {
                    if (data != "")
                    {
                        $("#imageryPage").append(data);
                    }
                }).always(function() {
                    HideLoading();
                    photosRendered = true;
                });
            }
        }

        if (page == "#contactPage") {
            // Load Contact via Ajax if not already loaded
            if (!contactRendered) {
                ShowLoading();
                $.get('/Home/GetContactContent', { id: 5046, template: "Template_6"}, function (data) {
                    if (data != "")
                    {
                        $("#contactPage").append(data);
                    }
                }).always(function() {
                    HideLoading();
                    contactRendered = true;
                });
            }
        }

         if (page == "#locationsPage") {
            // Load Locations via Ajax if not already loaded
             if (!locationsRendered) {
                 ShowLoading();

                 $.get('/Home/GetLocationsContent', { related_locations: null, template: "Template_6" }, function (data) {
                    if (data != "")
                    {
                        $("#locationsPage").append(data);
                    }
                }).always(function() {
                    HideLoading();
                    locationsRendered = true;
                });
            }
        }
    }

    function nextReview() {
        ScrollForReviews();
        GetReviewData(1);
    }

    function prevReview() {
        ScrollForReviews();
        GetReviewData(-1);
    }

    function GetReviewData(i)
    {
        if(i != 0){
            ShowLoading();
        }
        pageIndex = pageIndex + i;
        $.get('/Home/GetEnhancedTestimonialReviewInfo', {id: 5046, pageIndex: pageIndex, pageSize: pageSize, notReputation: notReputation, file: '_TemplateReviewContent'}, function (data) {
            if (data != "")
            {
                $(".reviewInfo").html(data);
            }
        }).always(function() {
            HideLoading();
        });
        SetPaginationButtons();
    }

    function GetPostsData(i)
    {
        if(i != 0){
            ShowLoading();
        }
        postsPageIndex = postsPageIndex + i;
        $.get('/Home/GetTestimonialPostsInfo', {id: 5046, program_id: 11, profileDomain: 'https://web.archive.org/web/20220405071626/https://hungrybearbonduelwi.com/', subdomain: 'hungrybearbonduelwi', testimonialSSL : 'False', domainSSL : 'True', pageIndex: postsPageIndex, pageSize: pageSize, file: '_TestimonialPostsContent'}, function (data) {
            if (data != "")
            {
                $(".postsInfo").html(data);
            }
        }).always(function() {
            HideLoading();
        });
        SetPostsPaginationButtons();
    }

    function GetPostsBanner()
    {
        ShowLoading();
        var bannerObj = null;
        $.ajax({
            method: "POST",
            url: "/Home/GetPostBanner",
            data:JSON.stringify(
            {
                banner: bannerObj,
                testimonialPageColor: '',
                postsColor: '#ffffff'
            }),
            contentType: 'application/json',
            success: function (data) {
                if(isMobile || isTablet){
                    setTimeout(function(){
                        $(".home-content").prepend(data);
                    }, 5000);
                }
                else{
                    $(".home-content").prepend(data);
                }

                //remove banner after 30 seconds regardless of mobile/tablet/desktop
                setTimeout(function(){
                    $("#posts-banner-alert").remove();
                }, 30000);
            }
        }).always(function() {
            HideLoading();
        });
    }

    function SetPaginationButtons()
    {
        //look ahead by one
        if(((pageIndex + 1) * pageSize) >= numOfReviews){
            $("#nextReview").prop('disabled', true);
        }
        else{
            $("#nextReview").prop('disabled', false);
        }

        if(pageIndex <= 0) {
            pageIndex = 0;
            $("#prevReview").prop('disabled', true);
        }
        else if (pageIndex > 0){
            $("#prevReview").prop('disabled', false);
        }
    }

    function SetPostsPaginationButtons()
    {
        //look ahead by one
        if(((postsPageIndex + 1) * pageSize) >= numOfPosts){
            $("#nextPosts").prop('disabled', true);
        }
        else{
            $("#nextPosts").prop('disabled', false);
        }

        if(postsPageIndex <= 0) {
            postsPageIndex = 0;
            $("#prevPosts").prop('disabled', true);
        }
        else if (postsPageIndex > 0){
            $("#prevPosts").prop('disabled', false);
        }
    }

    function validateReview(btn) {
        var successText = true;
        var successRating = true;
        successText = validateReviewLength();
        successRating = validateRating();
        return (successText && successRating);
    }

    function validateReviewLength(){
        var text = $('#review').val();
        var success = true;

        if ($.trim(text).length == 0) {
            $('#review').addClass('error');
            success = false;
        }
        return success;
    }

    function validateRating() {
        var rating = $('#starRating').val();
        var success = true;
        if (rating == "") {
            $('.br-widget').addClass('error');
            success = false;
        }
        return success;
    }

    function ShowLoading()
    {
        $("#loadingImg").show();
    }

    function HideLoading()
    {
        $("#loadingImg").hide();
    }

    function ClearReviewFields()
    {
        $('#starRating').barrating('clear');
        $("#review").val("");
        $("#review_alias").val("");
        $("#review_heading").val("");
        $("#reviewCaptcha").val("");
    }

    function checkMobile() {
        var windowsize = $(window).width();
        switch (true) {
        case /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent):
            isMobile = true;
            break;
        case windowsize < 800:
            isMobile = true;
            break;
        default:
            isMobile = false;
      }
    }

    function checkTablet() {
        var windowsize = $(window).width();
        switch (true) {
        case (windowsize >= 800) && (windowsize < 1200):
            isTablet = true;
            break;
        default:
            isTablet = false;
      }
    }

    function DisplayPhoto(imageUrl){
        bootbox.alert({
            message:'',
            size: "large",
            backdrop: true,
            buttons: {
                ok: {
                    className: 'btn-outline-dark',
                    label: 'Close'
                }
            }
        });
    }

    function DisplayPhotoSlider(index){
        if(!$(".slider-imagery").hasClass("slick-initialized"))
        {
            $('.slider-imagery').slick({
                slidesToShow: 1,
                slidesToScroll: 1,
                arrows: true,
                fade: false,
                adaptiveHeight: false,
                infinite: true,
                useTransform: true,
                speed: 400,
                cssEase: 'cubic-bezier(0.77, 0, 0.18, 1)',
                autoplay: true,
            });
        }

        $(".slider-imagery").slick('slickGoTo', index);

        $("#carouselImageryPhotoModal").modal('show');
    }

    function DisplayVideoSlider(index){
        if(!$(".slider-video").hasClass("slick-initialized"))
        {
            $('.slider-video').slick({
                slidesToShow: 1,
                slidesToScroll: 1,
                arrows: true,
                fade: false,
                adaptiveHeight: false,
                infinite: true,
                useTransform: true,
                speed: 400,
                cssEase: 'cubic-bezier(0.77, 0, 0.18, 1)',
            });
        }

        $(".slider-video").slick('slickGoTo', index);

        $("#carouselImageryVideoModal").modal('show');
    }

    function setFooterColor(hexColor)
    {
        //set footer text color based on background color
        var r = parseInt(hexColor.substr(1,2),16);
        var g = parseInt(hexColor.substr(3,2),16);
        var b = parseInt(hexColor.substr(5,2),16);
        var rgb = ((r*299)+(g*587)+(b*114))/1000;

        var textColor = (rgb >= 128) ? 'black' : 'white';
        //text needs to be black
        if(textColor == 'black')
        {
            //set header info
            if ($('.content-header').hasClass('light'))
            {
                $('.content-header').removeClass('light');
            }
            if (!$('.content-header').hasClass('dark'))
            {
                $('.content-header').addClass('dark');
            }

            //set navbar attributes
            if ($('.navbar-attribute').hasClass('light'))
            {
                $('.navbar-attribute').removeClass('light');
            }
            if (!$('.navbar-attribute').hasClass('dark'))
            {
                $('.navbar-attribute').addClass('dark');
            }

            //set navbar hours
            if ($('#navbar-hours').hasClass('light'))
            {
                $('#navbar-hours').removeClass('light');
            }
            if (!$('#navbar-hours').hasClass('dark'))
            {
                $('#navbar-hours').addClass('dark');
            }

            //set navbar hours-sm
            if ($('#navbar-hours-sm').hasClass('light'))
            {
                $('#navbar-hours-sm').removeClass('light');
            }
            if (!$('#navbar-hours-sm').hasClass('dark'))
            {
                $('#navbar-hours-sm').addClass('dark');
            }

            //set phone-nav-mobile
            if ($('.phone-nav-mobile').hasClass('light'))
            {
                $('.phone-nav-mobile').removeClass('light');
            }
            if (!$('.phone-nav-mobile').hasClass('dark'))
            {
                $('.phone-nav-mobile').addClass('dark');
            }

            //set footer info
            if($('#footer-address').hasClass('light'))
            {
                $('#footer-address').removeClass('light');
            }
            if(!$('#footer-address').hasClass('dark'))
            {
                $('#footer-address').addClass('dark');
            }

            //set phone link
            if($('#phoneLink').hasClass('light'))
            {
                $('#phoneLink').removeClass('light');
            }
            if(!$('#phoneLink').hasClass('dark'))
            {
                $('#phoneLink').addClass('dark');
            }

            //set terms of service link
            if($('#tosLink').hasClass('light'))
            {
                $('#tosLink').removeClass('light');
            }
